"use client";

import { useCallback, useEffect, useState } from "react";
import type { FilterState } from "./Filters";

const RANGES = ["24h", "7d", "30d", "90d"];
const PLATFORMS = ["all", "youtube", "tiktok"];

function valid(v: unknown): v is FilterState {
  const f = v as Partial<FilterState> | null;
  return !!f && RANGES.includes(String(f.range)) && PLATFORMS.includes(String(f.platform)) && (f.account === null || Number.isInteger(f.account));
}

/**
 * Filters that survive a reload and travel in the URL:
 * the link from the address bar opens the same view for a teammate, and without a link the
 * browser remembers the last view, so nobody has to re-pick channel and period every visit.
 */
export function useFilterState(storeKey: string, initial: FilterState) {
  const [f, setF] = useState<FilterState>(initial);

  useEffect(() => {
    try {
      const q = new URLSearchParams(window.location.search);
      if (q.has("range") || q.has("platform") || q.has("account")) {
        const a = Number(q.get("account"));
        const fromUrl = { range: q.get("range") ?? initial.range, platform: q.get("platform") ?? initial.platform, account: Number.isInteger(a) && a > 0 ? a : null };
        if (valid(fromUrl)) return setF(fromUrl);
      }
      const saved = JSON.parse(window.localStorage.getItem(storeKey) ?? "null");
      if (valid(saved)) setF(saved);
    } catch {
      /* storage can be blocked; the page still works with defaults */
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [storeKey]);

  const set = useCallback(
    (next: FilterState) => {
      setF(next);
      try {
        window.localStorage.setItem(storeKey, JSON.stringify(next));
        const q = new URLSearchParams(window.location.search);
        q.set("range",next.range);q.set("platform",next.platform);q.delete("account");
        if (next.account) q.set("account", String(next.account));
        window.history.replaceState(null, "", `${window.location.pathname}?${q}`);
      } catch {
        /* ignore */
      }
    },
    [storeKey],
  );
  return [f, set] as const;
}

src/db/schema.ts:
import {
  bigint,
  index,
  integer,
  pgEnum,
  pgTable,
  real,
  serial,
  text,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core";

export const platformEnum = pgEnum("platform", ["youtube", "tiktok"]);

/** A tracked YouTube channel or TikTok account. */
export const accounts = pgTable(
  "accounts",
  {
    id: serial("id").primaryKey(),
    platform: platformEnum("platform").notNull(),
    /** YouTube channel ID (UC...) or TikTok open_id. */
    externalId: text("external_id").notNull(),
    title: text("title").notNull(),
    handle: text("handle"),
    avatarUrl: text("avatar_url"),
    /** YouTube only: the channel's uploads playlist. */
    uploadsPlaylistId: text("uploads_playlist_id"),
    /** TikTok only: OAuth tokens, encrypted at rest (see lib/crypto.ts). */
    accessTokenEnc: text("access_token_enc"),
    refreshTokenEnc: text("refresh_token_enc"),
    accessTokenExpiresAt: timestamp("access_token_expires_at", { withTimezone: true }),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at", { withTimezone: true }),
    /** YouTube only: set when the channel owner connected YouTube Analytics (refresh_token_enc then holds the Google refresh token). */
    analyticsError: text("analytics_error"),
    lastPolledAt: timestamp("last_polled_at", { withTimezone: true }),
    lastError: text("last_error"),
    catalogSyncedAt: timestamp("catalog_synced_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [uniqueIndex("accounts_platform_external_uq").on(t.platform, t.externalId)],
);

/** Account-level counters captured on every poll. */
export const accountSnapshots = pgTable(
  "account_snapshots",
  {
    id: serial("id").primaryKey(),
    accountId: integer("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    takenAt: timestamp("taken_at", { withTimezone: true }).notNull(),
    followers: bigint("followers", { mode: "number" }),
    totalViews: bigint("total_views", { mode: "number" }),
    totalLikes: bigint("total_likes", { mode: "number" }),
    videoCount: integer("video_count"),
  },
  (t) => [index("account_snapshots_account_taken_idx").on(t.accountId, t.takenAt)],
);

export const videos = pgTable(
  "videos",
  {
    id: serial("id").primaryKey(),
    accountId: integer("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    platform: platformEnum("platform").notNull(),
    externalId: text("external_id").notNull(),
    title: text("title").notNull(),
    url: text("url"),
    thumbnailUrl: text("thumbnail_url"),
    publishedAt: timestamp("published_at", { withTimezone: true }),
    durationSec: integer("duration_sec"),
    description: text("description"),
    hashtags: text("hashtags").array().notNull().default([]),
    contentType: text("content_type"),
    game: text("game"),
    campaign: text("campaign"),
    editor: text("editor"),
    notes: text("notes"),
  },
  (t) => [
    uniqueIndex("videos_platform_external_uq").on(t.platform, t.externalId),
    index("videos_account_idx").on(t.accountId),
  ],
);

/** Per-video counters captured on every poll; the source of "views gained". */
export const videoSnapshots = pgTable(
  "video_snapshots",
  {
    id: serial("id").primaryKey(),
    videoId: integer("video_id")
      .notNull()
      .references(() => videos.id, { onDelete: "cascade" }),
    takenAt: timestamp("taken_at", { withTimezone: true }).notNull(),
    views: bigint("views", { mode: "number" }).notNull(),
    likes: bigint("likes", { mode: "number" }),
    comments: bigint("comments", { mode: "number" }),
    shares: bigint("shares", { mode: "number" }),
  },
  (t) => [index("video_snapshots_video_taken_idx").on(t.videoId, t.takenAt)],
);

/** YouTube Analytics (owner-only data: AVD, CTR). One row per channel and look-back window. */
export const channelAnalytics = pgTable(
  "channel_analytics",
  {
    id: serial("id").primaryKey(),
    accountId: integer("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    /** "7d" | "30d" | "90d" */
    rangeKey: text("range_key").notNull(),
    views: bigint("views", { mode: "number" }),
    impressions: bigint("impressions", { mode: "number" }),
    /** Click-through rate in percent, as returned by YouTube. */
    ctr: real("ctr"),
    avdSec: real("avd_sec"),
    avgViewPct: real("avg_view_pct"),
    fetchedAt: timestamp("fetched_at", { withTimezone: true }).notNull(),
  },
  (t) => [uniqueIndex("channel_analytics_uq").on(t.accountId, t.rangeKey)],
);

/** Same metrics per video, over the last 28 days. */
export const videoAnalytics = pgTable("video_analytics", {
  videoId: integer("video_id")
    .primaryKey()
    .references(() => videos.id, { onDelete: "cascade" }),
  views: bigint("views", { mode: "number" }),
  impressions: bigint("impressions", { mode: "number" }),
  ctr: real("ctr"),
  avdSec: real("avd_sec"),
  avgViewPct: real("avg_view_pct"),
  fetchedAt: timestamp("fetched_at", { withTimezone: true }).notNull(),
});

/** One row per poll run, so the UI can show freshness and failures. */
export const pollRuns = pgTable("poll_runs", {
  id: serial("id").primaryKey(),
  startedAt: timestamp("started_at", { withTimezone: true }).notNull(),
  finishedAt: timestamp("finished_at", { withTimezone: true }),
  accountsOk: integer("accounts_ok").notNull().default(0),
  accountsFailed: integer("accounts_failed").notNull().default(0),
  videosUpdated: integer("videos_updated").notNull().default(0),
});

/** Short-lived OAuth state for the TikTok connect flow (CSRF protection). */
export const oauthStates = pgTable("oauth_states", {
  state: text("state").primaryKey(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export type Account = typeof accounts.$inferSelect;
export type Platform = (typeof platformEnum.enumValues)[number];

/** Workspace targets shared with everyone viewing the monthly brief. */
export const monthlyGoals = pgTable("monthly_goals", {
  month: text("month").primaryKey(),
  views: bigint("views", { mode: "number" }).notNull().default(0),
  followers: bigint("followers", { mode: "number" }).notNull().default(0),
  publications: integer("publications").notNull().default(0),
});

