import { normalizeHashtag } from "./hashtags";
import { sql } from "drizzle-orm";
import type { Db } from "@/db/client";
import type { PlatformFilter } from "./metrics";
export const CONTENT_TYPES = ["Meme", "Highlights", "Mic check", "BTS", "Interview", "Announcement", "Sponsor", "Other"] as const;
export type InsightQuery = { platform: PlatformFilter; accountId?: number | null; days: number; hours: number; contentType?: string; game?: string; campaign?: string; hashtag?: string };
export type InsightVideo = {
  id: number; title: string; accountTitle: string; accountId: number; platform: "youtube" | "tiktok";
  publishedAt: string; thumbnailUrl: string | null; contentType: string | null; game: string | null; campaign: string | null; editor: string | null;
  hashtags?: string[];
  durationSec: number | null; views: number; likes: number; comments: number; shares: number;
  ageViews: number | null; ageEngagements: number | null; ageSampleAt: string | null;
};
export const median = (values: number[]) => {
  if (!values.length) return null;
  const a = [...values].sort((x, y) => x - y); const mid = Math.floor(a.length / 2);
  return a.length % 2 ? a[mid] : (a[mid - 1] + a[mid]) / 2;
};
export function groupInsights(items: InsightVideo[], dimension: "contentType" | "game" | "campaign" | "editor" = "contentType") {
  const groups = new Map<string, InsightVideo[]>();
  for (const v of items) {
    // Keep platforms and channels separate so channel size cannot skew content comparisons.
    const label = v[dimension] || "Untagged";
    const length = v.durationSec == null ? "Unknown duration" : v.durationSec <= 60 ? "Up to 60s" : v.durationSec <= 180 ? "61-180s" : "Over 3 min";
    const key = `${v.accountId}|${label}|${length}`;
    const group = groups.get(key) ?? []; group.push(v); groups.set(key, group);
  }
  return [...groups.entries()].map(([key, vs]) => {
    const eligible = vs.filter((v) => v.ageViews != null);
    return { key, label: vs[0][dimension] || "Untagged", accountTitle: vs[0].accountTitle, platform: vs[0].platform, length: key.split("|").pop()!, videos: vs.length, samples: eligible.length, medianViews: median(eligible.map((v) => v.ageViews!)), medianEngagementRate: median(eligible.filter((v) => v.ageViews! > 0).map((v) => v.ageEngagements! / v.ageViews! * 100)) };
  }).sort((a, b) => (b.medianViews ?? -1) - (a.medianViews ?? -1));
}
export async function getInsights(db: Db, q: InsightQuery, now = new Date()) {
  const start = new Date(now.getTime() - q.days * 86400000);
  const conditions = [sql`v.published_at >= ${start.toISOString()}::timestamptz`, sql`v.published_at <= ${now.toISOString()}::timestamptz`];
  if (q.platform !== "all") conditions.push(sql`a.platform = ${q.platform}`);
  if (q.accountId) conditions.push(sql`a.id = ${q.accountId}`);
  if (q.hashtag) conditions.push(sql`v.hashtags @> ARRAY[${normalizeHashtag(q.hashtag)}]::text[]`);
  if (q.contentType) conditions.push(sql`v.content_type = ${q.contentType}`);
  if (q.game) conditions.push(sql`v.game ilike ${q.game.replace(/[%_\\]/g, "\\$&")}`);
  if (q.campaign) conditions.push(sql`v.campaign ilike ${q.campaign.replace(/[%_\\]/g, "\\$&")}`);
  const result = await db.execute(sql`
    select v.id, v.title, a.title as "accountTitle", a.id as "accountId", a.platform,
      v.published_at as "publishedAt", v.thumbnail_url as "thumbnailUrl", v.duration_sec as "durationSec",
      v.content_type as "contentType", v.game, v.campaign, v.editor, v.hashtags,
      coalesce(latest.views,0)::float8 as views, coalesce(latest.likes,0)::float8 as likes,
      coalesce(latest.comments,0)::float8 as comments, coalesce(latest.shares,0)::float8 as shares,
      milestone.views::float8 as "ageViews", milestone.eng::float8 as "ageEngagements", milestone.taken_at as "ageSampleAt"
    from videos v join accounts a on a.id = v.account_id
    left join lateral (select * from video_snapshots s where s.video_id = v.id and s.taken_at <= ${now.toISOString()}::timestamptz order by s.taken_at desc limit 1) latest on true
    left join lateral (
      select s.views, coalesce(s.likes,0)+coalesce(s.comments,0)+coalesce(s.shares,0) as eng, s.taken_at from video_snapshots s
      where s.video_id = v.id
        and s.taken_at <= v.published_at + (${q.hours} * interval '1 hour')
        and s.taken_at >= v.published_at + ((${q.hours} - 1) * interval '1 hour')
        and v.published_at + (${q.hours} * interval '1 hour') <= ${now.toISOString()}::timestamptz
        and exists (select 1 from account_snapshots tracked where tracked.account_id = a.id and tracked.taken_at <= v.published_at)
      order by s.taken_at desc limit 1
    ) milestone on true
    where ${sql.join(conditions, sql` and `)} order by v.published_at desc`);
  const items = (result as unknown as { rows: InsightVideo[] }).rows;
  return { generatedAt: now.toISOString(), hours: q.hours, days: q.days, items, groups: groupInsights(items), eligible: items.filter((v) => v.ageViews != null).length };
}

src/lib/metrics.ts:
import { sql, type SQL } from "drizzle-orm";
import { normalizeHashtag } from "./hashtags";
import type { Db } from "@/db/client";

export const RANGES = { "24h": 1, "7d": 7, "30d": 30, "90d": 90 } as const;
export type RangeKey = keyof typeof RANGES;
export type PlatformFilter = "all" | "youtube" | "tiktok";

export interface Filters {
  range: RangeKey;
  platform: PlatformFilter;
  accountId?: number | null;
  now?: Date;
}

export interface VideoRow {
  id: number;
  accountId: number;
  accountTitle: string;
  platform: "youtube" | "tiktok";
  title: string;
  url: string | null;
  thumbnailUrl: string | null;
  publishedAt: string | null;
  durationSec: number | null;
  views: number;
  likes: number;
  comments: number;
  shares: number;
  viewsGained: number;
  engagementsGained: number;
  /** YouTube Analytics (owner-only), last 28 days. Null until the channel manager connects Analytics. */
  avdSec: number | null;
  ctr: number | null;
}

export interface AccountRow {
  id: number;
  platform: "youtube" | "tiktok";
  title: string;
  handle: string | null;
  avatarUrl: string | null;
  followers: number | null;
  followersGained: number | null;
  viewsGained: number;
  engagementsGained: number;
  videosPublished: number;
  lastPolledAt: string | null;
  lastError: string | null;
}

export interface SeriesPoint {
  t: string;
  youtube: number;
  tiktok: number;
}

export interface Dashboard {
  generatedAt: string;
  filters: { range: RangeKey; platform: PlatformFilter; accountId: number | null };
  lastPoll: { finishedAt: string | null; accountsOk: number; accountsFailed: number } | null;
  /** Date when every selected channel had started tracking. */
  trackingSince: string | null;
  comparisonReady: boolean;
  kpis: {
    followers: number;
    followersGained: number;
    followersGainedPrev: number;
    viewsGained: number;
    viewsGainedPrev: number;
    engagements: number;
    engagementsPrev: number;
    videosPublished: number;
    videosPublishedPrev: number;
  };
  /** Owner-only YouTube Analytics for the selected channels. 24h uses the 7-day window (Analytics is daily). */
  analytics: { rangeKey: "7d" | "30d" | "90d"; avdSec: number | null; ctr: number | null; impressions: number | null; connected: number; total: number };
  bucket: "hour" | "day";
  viewsSeries: SeriesPoint[];
  followersSeries: SeriesPoint[];
  /** Views gained per bucket for each account (keys are account ids). */
  accountViewsSeries: Record<number, number[]>;
  accounts: AccountRow[];
  topVideos: VideoRow[];
}

const DAY = 86400_000;
const iso = (d: Date) => d.toISOString();
const num = (v: unknown) => (v === null || v === undefined ? 0 : Number(v));

function scope(f: Filters, alias: { account: string }): SQL {
  const parts: SQL[] = [sql`true`];
  if (f.platform !== "all") parts.push(sql`${sql.raw(alias.account)}.platform = ${f.platform}`);
  if (f.accountId) parts.push(sql`${sql.raw(alias.account)}.id = ${f.accountId}`);
  return sql.join(parts, sql` and `);
}

async function rows<T>(db: Db, q: SQL): Promise<T[]> {
  const res = (await db.execute(q)) as unknown as { rows: T[] };
  return res.rows;
}

/**
 * Per-video gains between `start` and `end`: views at `end` minus views at `start`.
 * The baseline is the last snapshot at or before `start`; a video published inside
 * the window starts from 0; otherwise the first snapshot inside the window is used.
 */
function videoGainsQuery(f: Filters, start: Date, end: Date): SQL {
  return sql`
    select v.id, v.account_id, a.title as account_title, a.platform, v.title, v.url, v.thumbnail_url,
      v.published_at, v.duration_sec, v.content_type, v.description, v.hashtags,
      last.views, last.likes, last.comments, last.shares, va.avd_sec, va.ctr,
      greatest(last.views - coalesce(base.views,
        case when v.published_at >= ${iso(start)}::timestamptz and exists (select 1 from account_snapshots tracked where tracked.account_id = a.id and tracked.taken_at <= v.published_at) then 0 end, first.views, last.views), 0) as views_gained,
      greatest(
        (coalesce(last.likes,0) + coalesce(last.comments,0) + coalesce(last.shares,0)) -
        coalesce(base.eng, case when v.published_at >= ${iso(start)}::timestamptz and exists (select 1 from account_snapshots tracked where tracked.account_id = a.id and tracked.taken_at <= v.published_at) then 0 end, first.eng,
          coalesce(last.likes,0) + coalesce(last.comments,0) + coalesce(last.shares,0)), 0) as engagements_gained
    from videos v
    join accounts a on a.id = v.account_id
    left join video_analytics va on va.video_id = v.id
    join lateral (
      select views, likes, comments, shares from video_snapshots s
      where s.video_id = v.id and s.taken_at <= ${iso(end)}::timestamptz
      order by taken_at desc limit 1) last on true
    left join lateral (
      select views, coalesce(likes,0)+coalesce(comments,0)+coalesce(shares,0) as eng from video_snapshots s
      where s.video_id = v.id and s.taken_at <= ${iso(start)}::timestamptz
      order by taken_at desc limit 1) base on true
    left join lateral (
      select views, coalesce(likes,0)+coalesce(comments,0)+coalesce(shares,0) as eng from video_snapshots s
      where s.video_id = v.id and s.taken_at > ${iso(start)}::timestamptz and s.taken_at <= ${iso(end)}::timestamptz
      order by taken_at asc limit 1) first on true
    where ${scope(f, { account: "a" })}`;
}

interface RawVideo {
  id: number;
  account_id: number;
  account_title: string;
  platform: "youtube" | "tiktok";
  title: string;
  url: string | null;
  thumbnail_url: string | null;
  published_at: string | Date | null;
  duration_sec: number | null;
  views: number | string;
  likes: number | string | null;
  comments: number | string | null;
  shares: number | string | null;
  views_gained: number | string;
  engagements_gained: number | string;
  avd_sec: number | null;
  ctr: number | null;
}

const toIso = (v: string | Date | null) => (v === null ? null : new Date(v).toISOString());

function toVideo(r: RawVideo): VideoRow {
  return {
    id: r.id,
    accountId: r.account_id,
    accountTitle: r.account_title,
    platform: r.platform,
    title: r.title,
    url: r.url,
    thumbnailUrl: r.thumbnail_url,
    publishedAt: toIso(r.published_at),
    durationSec: r.duration_sec,
    views: num(r.views),
    likes: num(r.likes),
    comments: num(r.comments),
    shares: num(r.shares),
    viewsGained: num(r.views_gained),
    engagementsGained: num(r.engagements_gained),
    avdSec: r.avd_sec ?? null,
    ctr: r.ctr ?? null,
  };
}

/** Net follower change per account between start and end. */
function followerQuery(f: Filters, start: Date, end: Date): SQL {
  return sql`
    select a.id, last.followers as followers,
      last.followers - coalesce(base.followers, first.followers, last.followers) as gained
    from accounts a
    left join lateral (
      select followers from account_snapshots s
      where s.account_id = a.id and s.taken_at <= ${iso(end)}::timestamptz and s.followers is not null
      order by taken_at desc limit 1) last on true
    left join lateral (
      select followers from account_snapshots s
      where s.account_id = a.id and s.taken_at <= ${iso(start)}::timestamptz and s.followers is not null
      order by taken_at desc limit 1) base on true
    left join lateral (
      select followers from account_snapshots s
      where s.account_id = a.id and s.taken_at > ${iso(start)}::timestamptz and s.taken_at <= ${iso(end)}::timestamptz
        and s.followers is not null
      order by taken_at asc limit 1) first on true
    where ${scope(f, { account: "a" })}`;
}

/**
 * Gain per time bucket and platform. Each entity's value is reduced to its max per
 * bucket, then differenced against its previous bucket, so a video or account that
 * enters tracking never shows up as one giant spike.
 */
function seriesQuery(kind: "views" | "followers", f: Filters, start: Date, end: Date, unit: "hour" | "day"): SQL {
  const u = sql.raw(`'${unit}'`);
  const lookback = new Date(start.getTime() - (unit === "hour" ? DAY : 3 * DAY));
  const per =
    kind === "views"
      ? sql`select a.platform, a.id as account_id, s.video_id as entity, date_trunc(${u}, s.taken_at) as bucket, max(s.views) as value,
              min(v.published_at) as published_at
            from video_snapshots s join videos v on v.id = s.video_id join accounts a on a.id = v.account_id
            where s.taken_at > ${iso(lookback)}::timestamptz and s.taken_at <= ${iso(end)}::timestamptz
              and ${scope(f, { account: "a" })}
            group by 1, 2, 3, 4`
      : sql`select a.platform, a.id as account_id, s.account_id as entity, date_trunc(${u}, s.taken_at) as bucket, max(s.followers) as value,
              null::timestamptz as published_at
            from account_snapshots s join accounts a on a.id = s.account_id
            where s.followers is not null and s.taken_at > ${iso(lookback)}::timestamptz
              and s.taken_at <= ${iso(end)}::timestamptz and ${scope(f, { account: "a" })}
            group by 1, 2, 3, 4`;
  return sql`
    with per as (${per}),
    d as (
      select platform, account_id, bucket,
        coalesce(value - lag(value) over (partition by entity order by bucket),
          case when published_at >= bucket - ${sql.raw(`interval '1 ${unit}'`)} and exists (select 1 from account_snapshots tracked where tracked.account_id = per.account_id and tracked.taken_at <= published_at) then value end) as gain
      from per)
    select platform, account_id, bucket, sum(gain) as gain from d
    where bucket >= date_trunc(${u}, ${iso(start)}::timestamptz) and gain is not null
    group by 1, 2, 3 order by 3`;
}

interface SeriesRaw {
  platform: string;
  account_id: number;
  bucket: string | Date;
  gain: string | number;
}

/** Per-account gains aligned to the same buckets as the platform series. */
function accountSeries(raw: SeriesRaw[], points: SeriesPoint[]): Record<number, number[]> {
  const index = new Map(points.map((p, i) => [new Date(p.t).getTime(), i]));
  const out: Record<number, number[]> = {};
  for (const r of raw) {
    const i = index.get(new Date(r.bucket).getTime());
    if (i === undefined) continue;
    (out[r.account_id] ??= new Array(points.length).fill(0))[i] += num(r.gain);
  }
  return out;
}

function fillSeries(raw: SeriesRaw[], start: Date, end: Date, unit: "hour" | "day"): SeriesPoint[] {
  const step = unit === "hour" ? 3600_000 : DAY;
  const floor = (d: Date) => {
    const x = new Date(d);
    if (unit === "hour") x.setUTCMinutes(0, 0, 0);
    else x.setUTCHours(0, 0, 0, 0);
    return x.getTime();
  };
  const map = new Map<number, SeriesPoint>();
  for (let t = floor(start); t <= end.getTime(); t += step) map.set(t, { t: new Date(t).toISOString(), youtube: 0, tiktok: 0 });
  for (const r of raw) {
    const p = map.get(new Date(r.bucket).getTime());
    if (p && (r.platform === "youtube" || r.platform === "tiktok")) p[r.platform] += num(r.gain);
  }
  return [...map.values()];
}

const analyticsKey = (r: RangeKey) => (r === "24h" ? "7d" : r);

/** AVD is weighted by views and CTR by impressions, so a big channel counts for more than a small one. */
function analyticsSummary(range: RangeKey, rs: { views: number | null; impressions: number | null; ctr: number | null; avd_sec: number | null }[], total: number): Dashboard["analytics"] {
  const weighted = (value: (r: (typeof rs)[number]) => number | null, weight: (r: (typeof rs)[number]) => number | null) => {
    let sum = 0;
    let w = 0;
    for (const r of rs) {
      const v = value(r);
      const x = weight(r);
      if (v == null || !x) continue;
      sum += v * num(x);
      w += num(x);
    }
    return w ? sum / w : null;
  };
  const impressions = rs.some((r) => r.impressions != null) ? rs.reduce((s, r) => s + num(r.impressions), 0) : null;
  return {
    rangeKey: analyticsKey(range),
    avdSec: weighted((r) => r.avd_sec, (r) => r.views),
    ctr: weighted((r) => r.ctr, (r) => r.impressions),
    impressions,
    connected: rs.length,
    total,
  };
}

export async function getDashboard(db: Db, f: Filters): Promise<Dashboard> {
  // Postgres date_trunc uses the session time zone; keep buckets in UTC.
  await db.execute(sql`set time zone 'UTC'`);
  const now = f.now ?? new Date();
  const span = RANGES[f.range] * DAY;
  const start = new Date(now.getTime() - span);
  const prevStart = new Date(start.getTime() - span);
  const unit = f.range === "24h" ? "hour" : "day";

  const [cur, prev, fol, folPrev, accts, published, publishedPrev, viewsRaw, follRaw, lastPoll, since, anRows] = await Promise.all([
    rows<RawVideo>(db, videoGainsQuery(f, start, now)),
    rows<RawVideo>(db, videoGainsQuery(f, prevStart, start)),
    rows<{ id: number; followers: string | null; gained: string | null }>(db, followerQuery(f, start, now)),
    rows<{ id: number; gained: string | null }>(db, followerQuery(f, prevStart, start)),
    rows<{ id: number; platform: "youtube" | "tiktok"; title: string; handle: string | null; avatar_url: string | null; last_polled_at: string | Date | null; last_error: string | null }>(
      db,
      sql`select a.id, a.platform, a.title, a.handle, a.avatar_url, a.last_polled_at, a.last_error from accounts a where ${scope(f, { account: "a" })} order by a.platform, a.title`,
    ),
    rows<{ account_id: number; n: string }>(
      db,
      sql`select v.account_id, count(*) as n from videos v join accounts a on a.id = v.account_id
          where v.published_at > ${iso(start)}::timestamptz and ${scope(f, { account: "a" })} group by 1`,
    ),
    rows<{ n: string }>(
      db,
      sql`select count(*) as n from videos v join accounts a on a.id = v.account_id
          where v.published_at > ${iso(prevStart)}::timestamptz and v.published_at <= ${iso(start)}::timestamptz
            and ${scope(f, { account: "a" })}`,
    ),
    rows<SeriesRaw>(db, seriesQuery("views", f, start, now, unit)),
    rows<SeriesRaw>(db, seriesQuery("followers", f, start, now, unit)),
    rows<{ finished_at: string | Date | null; accounts_ok: number; accounts_failed: number }>(
      db,
      sql`select finished_at, accounts_ok, accounts_failed from poll_runs where finished_at is not null order by id desc limit 1`,
    ),
    rows<{ t: string | Date | null }>(
      db,
      sql`select case when count(first_seen) = count(*) then max(first_seen) end as t from (select a.id, min(s.taken_at) as first_seen from accounts a left join account_snapshots s on s.account_id = a.id where ${scope(f, { account: "a" })} group by a.id) coverage`,
    ),
    rows<{ views: number | null; impressions: number | null; ctr: number | null; avd_sec: number | null }>(
      db,
      sql`select ca.views, ca.impressions, ca.ctr, ca.avd_sec from channel_analytics ca join accounts a on a.id = ca.account_id
          where ca.range_key = ${analyticsKey(f.range)} and ${scope(f, { account: "a" })}`,
    ),
  ]);

  const videos = cur.map(toVideo);
  const sum = (xs: number[]) => xs.reduce((a, b) => a + b, 0);
  const folById = new Map(fol.map((r) => [r.id, r]));
  const pubById = new Map(published.map((r) => [r.account_id, num(r.n)]));

  const accounts: AccountRow[] = accts.map((a) => {
    const own = videos.filter((v) => v.accountId === a.id);
    const fr = folById.get(a.id);
    return {
      id: a.id,
      platform: a.platform,
      title: a.title,
      handle: a.handle,
      avatarUrl: a.avatar_url,
      followers: fr?.followers == null ? null : num(fr.followers),
      followersGained: fr?.gained == null ? null : num(fr.gained),
      viewsGained: sum(own.map((v) => v.viewsGained)),
      engagementsGained: sum(own.map((v) => v.engagementsGained)),
      videosPublished: pubById.get(a.id) ?? 0,
      lastPolledAt: toIso(a.last_polled_at),
      lastError: a.last_error,
    };
  });

  const prevVideos = prev.map(toVideo);
  const viewsSeries = fillSeries(viewsRaw, start, now, unit);
  return {
    generatedAt: now.toISOString(),
    filters: { range: f.range, platform: f.platform, accountId: f.accountId ?? null },
    lastPoll: lastPoll[0]
      ? { finishedAt: toIso(lastPoll[0].finished_at), accountsOk: lastPoll[0].accounts_ok, accountsFailed: lastPoll[0].accounts_failed }
      : null,
    trackingSince: toIso(since[0]?.t ?? null),
    comparisonReady: !!since[0]?.t && new Date(since[0].t) <= prevStart && fol.every((r) => r.followers != null),
    analytics: analyticsSummary(f.range, anRows, accts.filter((a) => a.platform === "youtube").length),
    kpis: {
      followers: sum(accounts.map((a) => a.followers ?? 0)),
      followersGained: sum(fol.map((r) => num(r.gained))),
      followersGainedPrev: sum(folPrev.map((r) => num(r.gained))),
      viewsGained: sum(videos.map((v) => v.viewsGained)),
      viewsGainedPrev: sum(prevVideos.map((v) => v.viewsGained)),
      engagements: sum(videos.map((v) => v.engagementsGained)),
      engagementsPrev: sum(prevVideos.map((v) => v.engagementsGained)),
      videosPublished: sum([...pubById.values()]),
      videosPublishedPrev: num(publishedPrev[0]?.n),
    },
    bucket: unit,
    viewsSeries,
    followersSeries: fillSeries(follRaw, start, now, unit),
    accountViewsSeries: accountSeries(viewsRaw, viewsSeries),
    accounts,
    topVideos: [...videos].sort((a, b) => b.viewsGained - a.viewsGained).slice(0, 25),
  };
}

export interface LibraryQuery {
  platform: PlatformFilter;
  accountId?: number | null;
  q?: string;
  sort: "newest" | "views" | "trending";
  duration?: "short" | "medium" | "long";
  publishedDays?: number;
  contentType?: string;
  hashtag?: string;
  page: number;
  pageSize?: number;
  now?: Date;
}

/** Video library grid: every tracked video with its latest numbers and 24h gain. */
export async function getLibrary(db: Db, query: LibraryQuery): Promise<{ total: number; items: VideoRow[] }> {
  const now = query.now ?? new Date();
  const f: Filters = { range: "24h", platform: query.platform, accountId: query.accountId };
  const pageSize = Math.min(query.pageSize ?? 24, 60);
  const offset = Math.max(0, (query.page - 1) * pageSize);
  const search = query.q?.trim() ? sql`and concat(g.title, ' ', g.description) ilike ${"%" + query.q.trim().replace(/[%_\\]/g, "\\$&") + "%"}` : sql``;
  const extra: SQL[] = [];
  if (query.duration === "short") extra.push(sql`g.duration_sec <= 60`);
  if (query.duration === "medium") extra.push(sql`g.duration_sec > 60 and g.duration_sec <= 180`);
  if (query.duration === "long") extra.push(sql`g.duration_sec > 180`);
  if (query.publishedDays) extra.push(sql`g.published_at >= ${iso(new Date(now.getTime() - query.publishedDays * DAY))}::timestamptz`);
  if (query.hashtag) extra.push(sql`g.hashtags @> ARRAY[${normalizeHashtag(query.hashtag)}]::text[]`);
  if (query.contentType) extra.push(sql`g.content_type = ${query.contentType}`);
  const where = extra.length ? sql`and ${sql.join(extra, sql` and `)}` : sql``;
  const order =
    query.sort === "views" ? sql`g.views desc` : query.sort === "trending" ? sql`g.views_gained desc` : sql`g.published_at desc nulls last`;
  const base = videoGainsQuery(f, new Date(now.getTime() - DAY), now);
  const [items, total] = await Promise.all([
    rows<RawVideo>(db, sql`select * from (${base}) g where true ${search} ${where} order by ${order}, g.id desc limit ${pageSize} offset ${offset}`),
    rows<{ n: string }>(db, sql`select count(*) as n from (${base}) g where true ${search} ${where}`),
  ]);
  return { total: num(total[0]?.n), items: items.map(toVideo) };
}

/* ---------- Monthly report (for management) ---------- */

const VN_OFFSET = 7 * 3600_000; // months follow Vietnam time, not UTC

export interface MonthRange {
  month: string;
  start: Date;
  end: Date;
  prevStart: Date;
  prevEnd: Date;
  /** True once the month is over, so its numbers no longer change. */
  complete: boolean;
}

/** "2026-09" -> boundaries in Vietnam time. The end is capped at `now` for the running month. */
export function monthRange(month: string, now = new Date()): MonthRange | null {
  const m = /^(\d{4})-(0[1-9]|1[0-2])$/.exec(month);
  if (!m) return null;
  const y = Number(m[1]);
  const mo = Number(m[2]);
  const start = new Date(Date.UTC(y, mo - 1, 1) - VN_OFFSET);
  const nextStart = new Date(Date.UTC(y, mo, 1) - VN_OFFSET);
  const prevStart = new Date(Date.UTC(y, mo - 2, 1) - VN_OFFSET);
  const complete = now >= nextStart;
  if (now < start) return null;
  const end = complete ? nextStart : now;
  const prevEnd = complete ? start : new Date(Math.min(start.getTime(), prevStart.getTime() + end.getTime() - start.getTime()));
  return { month, start, end, prevStart, prevEnd, complete };
}

/** The month the report page opens on: this month. */
export const currentMonth = (now = new Date()) => {
  const vn = new Date(now.getTime() + VN_OFFSET);
  return `${vn.getUTCFullYear()}-${String(vn.getUTCMonth() + 1).padStart(2, "0")}`;
};

export interface MonthlyReport {
  month: string;
  generatedAt: string;
  complete: boolean;
  comparisonReady: boolean;
  period: { start: string; end: string; previousStart: string; previousEnd: string };
  trackingSince: string | null;
  kpis: {
    viewsGained: number;
    viewsGainedPrev: number;
    engagements: number;
    engagementsPrev: number;
    followers: number;
    followersGained: number;
    followersGainedPrev: number;
    videosPublished: number;
    videosPublishedPrev: number;
  };
  accounts: (AccountRow & { avdSec: number | null })[];
  topVideos: VideoRow[];
  /** Average view duration over the last 30 days, weighted by views. Owner-only data, so it can be missing. */
  avdSec: number | null;
}

export async function getMonthlyReport(db: Db, month: string, now = new Date()): Promise<MonthlyReport | null> {
  const r = monthRange(month, now);
  if (!r) return null;
  await db.execute(sql`set time zone 'UTC'`);
  const f: Filters = { range: "30d", platform: "all", accountId: null };
  const [cur, prev, fol, folPrev, accts, published, publishedPrev, since, an] = await Promise.all([
    rows<RawVideo>(db, videoGainsQuery(f, r.start, r.end)),
    rows<RawVideo>(db, videoGainsQuery(f, r.prevStart, r.prevEnd)),
    rows<{ id: number; followers: string | null; gained: string | null }>(db, followerQuery(f, r.start, r.end)),
    rows<{ id: number; gained: string | null }>(db, followerQuery(f, r.prevStart, r.prevEnd)),
    rows<{ id: number; platform: "youtube" | "tiktok"; title: string; handle: string | null; avatar_url: string | null; last_polled_at: string | Date | null; last_error: string | null }>(
      db,
      sql`select a.id, a.platform, a.title, a.handle, a.avatar_url, a.last_polled_at, a.last_error from accounts a order by a.platform, a.title`,
    ),
    rows<{ account_id: number; n: string }>(db, sql`select v.account_id, count(*) as n from videos v where v.published_at >= ${iso(r.start)}::timestamptz and v.published_at < ${iso(r.end)}::timestamptz group by 1`),
    rows<{ n: string }>(db, sql`select count(*) as n from videos v where v.published_at >= ${iso(r.prevStart)}::timestamptz and v.published_at < ${iso(r.prevEnd)}::timestamptz`),
    rows<{ t: string | Date | null }>(db, sql`select case when count(t) = count(*) then max(t) end as t from (select a.id, min(s.taken_at) as t from accounts a left join account_snapshots s on s.account_id = a.id group by a.id) coverage`),
    rows<{ account_id: number; views: number | null; avd_sec: number | null }>(db, sql`select account_id, views, avd_sec from channel_analytics where range_key = ${"month:" + month}`),
  ]);

  const sum = (xs: number[]) => xs.reduce((a, b) => a + b, 0);
  const videos = cur.map(toVideo);
  const folById = new Map(fol.map((x) => [x.id, x]));
  const pubById = new Map(published.map((x) => [x.account_id, num(x.n)]));
  const anById = new Map(an.map((x) => [x.account_id, x]));

  const accounts = accts.map((a) => {
    const own = videos.filter((v) => v.accountId === a.id);
    const fr = folById.get(a.id);
    return {
      id: a.id,
      platform: a.platform,
      title: a.title,
      handle: a.handle,
      avatarUrl: a.avatar_url,
      followers: fr?.followers == null ? null : num(fr.followers),
      followersGained: fr?.gained == null ? null : num(fr.gained),
      viewsGained: sum(own.map((v) => v.viewsGained)),
      engagementsGained: sum(own.map((v) => v.engagementsGained)),
      videosPublished: pubById.get(a.id) ?? 0,
      lastPolledAt: toIso(a.last_polled_at),
      lastError: a.last_error,
      avdSec: anById.get(a.id)?.avd_sec ?? null,
    };
  });

  const anWeight = an.filter((x) => x.avd_sec != null && x.views);
  const anViews = sum(anWeight.map((x) => num(x.views)));
  return {
    month: r.month,
    generatedAt: now.toISOString(),
    complete: r.complete,
    comparisonReady: !!since[0]?.t && new Date(since[0].t) <= r.prevStart && fol.every((x) => x.followers != null),
    period: { start: iso(r.start), end: iso(r.end), previousStart: iso(r.prevStart), previousEnd: iso(r.prevEnd) },
    trackingSince: toIso(since[0]?.t ?? null),
    kpis: {
      viewsGained: sum(videos.map((v) => v.viewsGained)),
      viewsGainedPrev: sum(prev.map(toVideo).map((v) => v.viewsGained)),
      engagements: sum(videos.map((v) => v.engagementsGained)),
      engagementsPrev: sum(prev.map(toVideo).map((v) => v.engagementsGained)),
      followers: sum(accounts.map((a) => a.followers ?? 0)),
      followersGained: sum(fol.map((x) => num(x.gained))),
      followersGainedPrev: sum(folPrev.map((x) => num(x.gained))),
      videosPublished: sum([...pubById.values()]),
      videosPublishedPrev: num(publishedPrev[0]?.n),
    },
    accounts,
    topVideos: [...videos].sort((a, b) => b.viewsGained - a.viewsGained).slice(0, 5),
    avdSec: anViews ? sum(anWeight.map((x) => num(x.avd_sec) * num(x.views))) / anViews : null,
  };
}

/** Videos published in the last 48 hours, newest first, with their pace so far. */
export interface LatestUpload extends VideoRow {
  hoursOld: number;
  viewsPerHour: number;
}

export async function getLatestUploads(db: Db, f: Pick<Filters, "platform" | "accountId">, now = new Date()): Promise<LatestUpload[]> {
  await db.execute(sql`set time zone 'UTC'`);
  const ff: Filters = { range: "24h", platform: f.platform, accountId: f.accountId ?? null };
  const since = new Date(now.getTime() - 2 * DAY);
  const fresh = await rows<RawVideo>(
    db,
    sql`select * from (${videoGainsQuery(ff, new Date(now.getTime() - DAY), now)}) g where g.published_at >= ${iso(since)}::timestamptz order by g.published_at desc limit 12`,
  );
  return fresh.map(toVideo).map((v) => {
    const hoursOld = Math.max(1, (now.getTime() - new Date(v.publishedAt ?? now).getTime()) / 3600_000);
    return { ...v, hoursOld, viewsPerHour: v.views / hoursOld };
  });
}

src/lib/poll.ts:
import { and, eq, gte, inArray, lt, sql } from "drizzle-orm";
import type { Db } from "@/db/client";
import { accounts, accountSnapshots, channelAnalytics, oauthStates, pollRuns, videoAnalytics, videos, videoSnapshots, type Account, type Platform } from "@/db/schema";
import { extractHashtags } from "./hashtags";
import { decrypt, encrypt } from "./crypto";
import { fetchVideos, queryVideos, fetchUser, refreshTokens, tiktokConfig, type TikTokConfig } from "./tiktok";
import { analyticsConfig, fetchChannelStats, fetchMonthStats, fetchVideoStats, myChannelId, refreshAccessToken } from "./ytAnalytics";
import { fetchChannels, fetchRecentVideos, fetchVideoIds, parseChannelInput, resolveChannel, type FetchFn } from "./youtube";

const TRACK_FROM = "2026-01-01T00:00:00.000Z";

export interface PollOptions {
  now?: Date;
  fetchFn?: FetchFn;
  youtubeApiKey?: string;
  tiktok?: TikTokConfig | null;
  /** Recent videos tracked per account. */
  videosPerAccount?: number;
  /** Channels that must always be tracked (defaults to the YOUTUBE_CHANNELS env var). */
  configuredChannels?: string[];
}

export interface PollResult {
  accountsOk: number;
  accountsFailed: number;
  videosUpdated: number;
  errors: { accountId: number; title: string; error: string }[];
}

interface VideoInput {
  id: string;
  title: string;
  description?: string | null;
  url: string | null;
  thumbnailUrl: string | null;
  publishedAt: string | null;
  durationSec: number | null;
  views: number;
  likes: number | null;
  comments: number | null;
  shares?: number | null;
}

async function recordVideos(db: Db, account: Account, list: VideoInput[], now: Date): Promise<number> {
  if (list.length === 0) return 0;
  const rows = await db
    .insert(videos)
    .values(
      list.map((v) => ({
        accountId: account.id,
        platform: account.platform,
        externalId: v.id,
        title: v.title,
        url: v.url,
        thumbnailUrl: v.thumbnailUrl,
        publishedAt: v.publishedAt ? new Date(v.publishedAt) : null,
        durationSec: v.durationSec,
        description: v.description ?? null,
        hashtags: extractHashtags(v.title, v.description),
      })),
    )
    .onConflictDoUpdate({
      target: [videos.platform, videos.externalId],
      set: {
        title: sqlExcluded("title"),
        url: sqlExcluded("url"),
        thumbnailUrl: sqlExcluded("thumbnail_url"),
        durationSec: sqlExcluded("duration_sec"),
        description: sqlExcluded("description"),
        hashtags: sqlExcluded("hashtags"),
      },
    })
    .returning({ id: videos.id, externalId: videos.externalId });
  const idByExternal = new Map(rows.map((r) => [r.externalId, r.id]));
  await db.insert(videoSnapshots).values(
    list.map((v) => ({
      videoId: idByExternal.get(v.id)!,
      takenAt: now,
      views: v.views,
      likes: v.likes,
      comments: v.comments,
      shares: v.shares ?? null,
    })),
  );
  return list.length;
}

// drizzle has no helper for EXCLUDED.<col>; keep the raw SQL in one place.
function sqlExcluded(column: string) {
  return sql.raw(`excluded.${column}`);
}

async function pollYouTube(db: Db, list: Account[], opts: Required<Pick<PollOptions, "fetchFn" | "videosPerAccount">> & { apiKey: string; now: Date }, result: PollResult) {
  if (list.length === 0) return;
  const channels = await fetchChannels(list.map((a) => a.externalId), opts.apiKey, opts.fetchFn);
  const byId = new Map(channels.map((c) => [c.id, c]));
  for (const account of list) {
    try {
      const ch = byId.get(account.externalId);
      if (!ch) throw new Error("Channel not returned by YouTube (deleted or private?).");
      await db.insert(accountSnapshots).values({
        accountId: account.id,
        takenAt: opts.now,
        followers: ch.subscribers,
        totalViews: ch.totalViews,
        videoCount: ch.videoCount,
      });
      const uploads = ch.uploadsPlaylistId ?? account.uploadsPlaylistId;
      const discover = !account.catalogSyncedAt || opts.now.getTime() - account.catalogSyncedAt.getTime() >= 86400000;
      const recent = uploads ? await fetchRecentVideos(uploads, opts.apiKey, discover ? 5000 : opts.videosPerAccount, opts.fetchFn, TRACK_FROM) : [];
      const known = await db.select({ externalId: videos.externalId }).from(videos).where(and(eq(videos.accountId, account.id), gte(videos.publishedAt, new Date(TRACK_FROM))));
      const freshIds = new Set(recent.map((v) => v.id));
      const older = await fetchVideoIds(known.map((v) => v.externalId).filter((id) => !freshIds.has(id)), opts.apiKey, opts.fetchFn);
      const vids = [...recent, ...older].filter((v) => v.publishedAt && v.publishedAt >= TRACK_FROM);
      result.videosUpdated += await recordVideos(
        db,
        account,
        vids.map((v) => ({ ...v, url: `https://www.youtube.com/watch?v=${v.id}` })),
        opts.now,
      );
      await db
        .update(accounts)
        .set({ title: ch.title, handle: ch.handle, avatarUrl: ch.avatarUrl, uploadsPlaylistId: uploads, ...(discover ? { catalogSyncedAt: opts.now } : {}), lastPolledAt: opts.now, lastError: null })
        .where(eq(accounts.id, account.id));
      result.accountsOk++;
    } catch (e) {
      await fail(db, account, e, result);
    }
  }
}

/** Returns a usable access token, refreshing (and persisting) it when close to expiry. */
async function tiktokAccessToken(db: Db, account: Account, cfg: TikTokConfig, fetchFn: FetchFn, now: Date): Promise<string> {
  if (!account.accessTokenEnc || !account.refreshTokenEnc) throw new Error("TikTok account is not connected.");
  const expires = account.accessTokenExpiresAt?.getTime() ?? 0;
  if (expires - now.getTime() > 10 * 60 * 1000) return decrypt(account.accessTokenEnc);
  if (account.refreshTokenExpiresAt && account.refreshTokenExpiresAt.getTime() <= now.getTime()) {
    throw new Error("TikTok authorisation expired. Reconnect this account.");
  }
  const t = await refreshTokens(cfg, decrypt(account.refreshTokenEnc), fetchFn, now);
  await db
    .update(accounts)
    .set({
      accessTokenEnc: encrypt(t.accessToken),
      refreshTokenEnc: encrypt(t.refreshToken),
      accessTokenExpiresAt: t.accessTokenExpiresAt,
      refreshTokenExpiresAt: t.refreshTokenExpiresAt,
    })
    .where(eq(accounts.id, account.id));
  return t.accessToken;
}

async function pollTikTok(db: Db, list: Account[], cfg: TikTokConfig, fetchFn: FetchFn, limit: number, now: Date, result: PollResult) {
  for (const account of list) {
    try {
      const token = await tiktokAccessToken(db, account, cfg, fetchFn, now);
      const user = await fetchUser(token, fetchFn);
      const discover = !account.catalogSyncedAt || now.getTime() - account.catalogSyncedAt.getTime() >= 86400000;
      const recent = await fetchVideos(token, discover ? 5000 : limit, fetchFn, TRACK_FROM);
      const known = await db.select({ externalId: videos.externalId }).from(videos).where(and(eq(videos.accountId, account.id), gte(videos.publishedAt, new Date(TRACK_FROM))));
      const freshIds = new Set(recent.map((v) => v.id));
      const older = await queryVideos(token, known.map((v) => v.externalId).filter((id) => !freshIds.has(id)), fetchFn);
      const vids = [...recent, ...older].filter((v) => v.publishedAt && v.publishedAt >= TRACK_FROM);
      await db.insert(accountSnapshots).values({
        accountId: account.id,
        takenAt: now,
        followers: user.followers,
        totalLikes: user.likes,
        videoCount: user.videoCount,
      });
      result.videosUpdated += await recordVideos(db, account, vids, now);
      await db
        .update(accounts)
        .set({ title: user.displayName, avatarUrl: user.avatarUrl, ...(discover ? { catalogSyncedAt: now } : {}), lastPolledAt: now, lastError: null })
        .where(eq(accounts.id, account.id));
      result.accountsOk++;
    } catch (e) {
      await fail(db, account, e, result);
    }
  }
}

const ANALYTICS_EVERY_MS = 6 * 3600_000;
const ANALYTICS_RANGES = [7, 30, 90];

/** Owner-only YouTube Analytics (AVD, CTR) for channels whose manager connected them. The data lags ~2 days, so every 6 hours is plenty. */
async function pollAnalytics(db: Db, list: Account[], fetchFn: FetchFn, now: Date, result: PollResult) {
  const cfg = analyticsConfig("");
  if (!cfg) return;
  for (const account of list.filter((a) => a.refreshTokenEnc)) {
    try {
      const [last] = await db.select({ at: sql<string | null>`max(${channelAnalytics.fetchedAt})` }).from(channelAnalytics).where(eq(channelAnalytics.accountId, account.id));
      if (last?.at && now.getTime() - new Date(last.at).getTime() < ANALYTICS_EVERY_MS) continue;
      const access = await refreshAccessToken(cfg, decrypt(account.refreshTokenEnc!), fetchFn);
      // Re-check which channel this token really owns before trusting its numbers.
      if ((await myChannelId(access, fetchFn)) !== account.externalId) throw new Error("The connected Google account no longer owns this channel. Reconnect it.");
      for (const days of ANALYTICS_RANGES) {
        const s = await fetchChannelStats(access, account.externalId, days, now, fetchFn);
        const row = { accountId: account.id, rangeKey: `${days}d`, ...s, fetchedAt: now };
        await db.insert(channelAnalytics).values(row).onConflictDoUpdate({ target: [channelAnalytics.accountId, channelAnalytics.rangeKey], set: row });
      }
      const vn = new Date(now.getTime() + 7 * 3600000);
      for (let i = 0; i < 6; i++) {
        const d = new Date(Date.UTC(vn.getUTCFullYear(), vn.getUTCMonth() - i, 1));
        const month = d.toISOString().slice(0, 7);
        const key = `month:${month}`;
        const [cached] = await db.select().from(channelAnalytics).where(and(eq(channelAnalytics.accountId, account.id), eq(channelAnalytics.rangeKey, key)));
        // Final months are immutable after the source's reporting delay has passed.
        if (i > 0 && cached && cached.fetchedAt.getTime() > new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 8)).getTime()) continue;
        const s = await fetchMonthStats(access, account.externalId, month, now, fetchFn);
        const row = { accountId: account.id, rangeKey: key, ...s, fetchedAt: now };
        await db.insert(channelAnalytics).values(row).onConflictDoUpdate({ target: [channelAnalytics.accountId, channelAnalytics.rangeKey], set: row });
      }
      const perVideo = await fetchVideoStats(access, account.externalId, 28, now, fetchFn);
      const known = perVideo.size
        ? await db.select({ id: videos.id, externalId: videos.externalId }).from(videos).where(and(eq(videos.accountId, account.id), inArray(videos.externalId, [...perVideo.keys()])))
        : [];
      for (const v of known) {
        const row = { videoId: v.id, ...perVideo.get(v.externalId)!, fetchedAt: now };
        await db.insert(videoAnalytics).values(row).onConflictDoUpdate({ target: videoAnalytics.videoId, set: row });
      }
      await db.update(accounts).set({ analyticsError: null }).where(eq(accounts.id, account.id));
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      result.errors.push({ accountId: account.id, title: `${account.title} (analytics)`, error: msg });
      await db.update(accounts).set({ analyticsError: msg.slice(0, 500) }).where(eq(accounts.id, account.id));
    }
  }
}

async function fail(db: Db, account: Account, e: unknown, result: PollResult) {
  const msg = e instanceof Error ? e.message : String(e);
  result.accountsFailed++;
  result.errors.push({ accountId: account.id, title: account.title, error: msg });
  await db.update(accounts).set({ lastError: msg.slice(0, 500) }).where(eq(accounts.id, account.id));
}

/** YOUTUBE_CHANNELS: comma-separated @handles, channel IDs or URLs. */
export function configuredYouTubeChannels(): string[] {
  return (process.env.YOUTUBE_CHANNELS ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
}

/**
 * Adds configured channels that are not tracked yet, so a fresh deployment fills
 * itself without anyone using the Channels page. Costs 1 quota unit per new channel.
 */
async function ensureConfiguredChannels(db: Db, inputs: string[], apiKey: string, fetchFn: FetchFn, result: PollResult) {
  if (inputs.length === 0) return;
  const existing = await db.select({ externalId: accounts.externalId, handle: accounts.handle }).from(accounts).where(eq(accounts.platform, "youtube"));
  const ids = new Set(existing.map((a) => a.externalId));
  const handles = new Set(existing.map((a) => a.handle?.toLowerCase()).filter(Boolean));
  for (const input of inputs) {
    try {
      const parsed = parseChannelInput(input);
      if ("id" in parsed ? ids.has(parsed.id) : handles.has(parsed.handle.toLowerCase())) continue;
      const ch = await resolveChannel(input, apiKey, fetchFn);
      await db
        .insert(accounts)
        .values({ platform: "youtube", externalId: ch.id, title: ch.title, handle: ch.handle, avatarUrl: ch.avatarUrl, uploadsPlaylistId: ch.uploadsPlaylistId })
        .onConflictDoNothing();
      ids.add(ch.id);
      if (ch.handle) handles.add(ch.handle.toLowerCase());
    } catch (e) {
      result.errors.push({ accountId: 0, title: input, error: e instanceof Error ? e.message : String(e) });
    }
  }
}

export async function pollAll(db: Db, options: PollOptions = {}): Promise<PollResult> {
  const now = options.now ?? new Date();
  const fetchFn = options.fetchFn ?? fetch;
  const videosPerAccount = options.videosPerAccount ?? 50;
  const apiKey = options.youtubeApiKey ?? process.env.YOUTUBE_API_KEY;
  const tt = options.tiktok === undefined ? tiktokConfig() : options.tiktok;
  const result: PollResult = { accountsOk: 0, accountsFailed: 0, videosUpdated: 0, errors: [] };

  const [run] = await db.insert(pollRuns).values({ startedAt: now }).returning({ id: pollRuns.id });
  if (apiKey) await ensureConfiguredChannels(db, options.configuredChannels ?? configuredYouTubeChannels(), apiKey, fetchFn, result);
  const all = await db.select().from(accounts);
  const byPlatform = (p: Platform) => all.filter((a) => a.platform === p);

  const yt = byPlatform("youtube");
  if (yt.length) {
    if (!apiKey) {
      for (const a of yt) await fail(db, a, new Error("YOUTUBE_API_KEY is not set."), result);
    } else {
      try {
        await pollYouTube(db, yt, { apiKey, fetchFn, videosPerAccount, now }, result);
      } catch (e) {
        // A failed batch lookup (bad key, quota exceeded) fails every YouTube account.
        for (const a of yt) await fail(db, a, e, result);
      }
    }
  }

  if (yt.length) await pollAnalytics(db, yt, fetchFn, now, result);

  const tk = byPlatform("tiktok");
  if (tk.length) {
    if (!tt) for (const a of tk) await fail(db, a, new Error("TikTok app credentials are not set."), result);
    else await pollTikTok(db, tk, tt, fetchFn, Math.min(videosPerAccount, 60), now, result);
  }

  await db
    .update(pollRuns)
    .set({ finishedAt: new Date(), accountsOk: result.accountsOk, accountsFailed: result.accountsFailed, videosUpdated: result.videosUpdated })
    .where(eq(pollRuns.id, run.id));
  // Expired OAuth states are useless; keep the table small.
  await db.delete(oauthStates).where(lt(oauthStates.createdAt, new Date(now.getTime() - 15 * 60 * 1000)));
  return result;
}

